   import altair as altimport pandas as pddef create_main_chart(data, chart_type='line'):    normalized = data.div(data.iloc[0])    plot_data = normalized.reset_index().melt(        id_vars=['Date'],         var_name='Ticker',         value_name='Normalized Price'    )        if chart_type == 'line':        chart = (            alt.Chart(plot_data)            .mark_line(point=True)            .encode(                alt.X('Date:T', title='Date'),                alt.Y('Normalized Price:Q', title='Normalized Price'),                alt.Color('Ticker:N', title='Instrument'),            )            .properties(height=400)            .interactive()        )    elif chart_type == 'area':        chart = (            alt.Chart(plot_data)            .mark_area(opacity=0.3)            .encode(                alt.X('Date:T', title='Date'),                alt.Y('Normalized Price:Q', title='Normalized Price'),                alt.Color('Ticker:N', title='Instrument'),            )            .properties(height=400)        )    return chartdef create_comparison_charts(data):    normalized = data.div(data.iloc[0])    charts = []    for ticker in normalized.columns:        peers = normalized.drop(columns=[ticker])        if not peers.empty:            peer_avg = peers.mean(axis=1)        else:            peer_avg = pd.Series(1.0, index=normalized.index)                plot_data = pd.DataFrame({            'Date': normalized.index,            ticker: normalized[ticker],            'Peer Average': peer_avg        }).melt(id_vars=['Date'], var_name='Series', value_name='Price')                chart = (            alt.Chart(plot_data)            .mark_line()            .encode(                alt.X('Date:T'),                alt.Y('Price:Q'),                alt.Color('Series:N'),            )            .properties(title=f'{ticker} vs Peer Average', height=250)        )        charts.append(chart)    return charts